Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {        
        METPlannerCodeSetup METPlannerCodeSetup; 

        select firstonly1 PlannerCodePersonnelNumber from METPlannerCodeSetup 
            where METPlannerCodeSetup.PlannerCode == this.METPOPlannerCode;
        
        HcmWorker HcmWorker = HcmWorker::find(METPlannerCodeSetup.PlannerCodePersonnelNumber);

        this.METPOPlannerContactName    = HcmWorker.name();
        this.METPOPlannerContactEmail   = HcmWorker.email();
        this.METPOPlannerContactPhone   = HcmWorker.phone();

        //Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> Begin
        PurchTable PurchTable = PurchTable::find(this.PurchaseOrderNumber);
        InventLocation InventLocation = InventLocation::find(PurchTable.InventLocationId);
        if(InventLocation.METUseDevAddressforShiptoGLNSetting)
        {
            this.METPODeliveryShiptoGLN = PurchTable.deliveryAddress().METPODeliveryShiptoGLN;
        }
        else
        {
            this.METPODeliveryShiptoGLN = InventLocation.METPODeliveryShiptoGLN;
        }
        //Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> Begin

        //MPJ-28494 - PO FSD enhancements v3 IHG edi and change fields, based on parameter isn't working - Data entity changes
        METPurchTable   metPurchTable       = METPurchTable::findByPurchTable(PurchTable.RecId);
        this.METPOSubMode                   = metPurchTable.POSubMode;
        this.METPOExpressReceiptSetting     = metPurchTable.POExpressReceiptSetting;
        this.METPOASNSetting                = metPurchTable.POASNSetting;
        this.METPOMinOrderValue             = metPurchTable.POMinOrderValue;
        this.METPOIHGEmailEDIAddress        = metPurchTable.POIHGEmailEDIAddress;
        this.METPOChngSubMode               = metPurchTable.POChngSubMode;
        this.METPOIHGEmailEDIAddressChnge   = metPurchTable.POIHGEmailEDIAddressChnge;
        next postload();
    }
